const API = '/api/v1';
const state = { token: localStorage.getItem('hv-token'), refreshToken: localStorage.getItem('hv-refresh'), user: null, view: 'command', eventSource: null, playback: null, playbackTimer: null, layers: JSON.parse(localStorage.getItem('hv-layers') || '{}') };
const $ = (s) => document.querySelector(s);
const escapeHtml = (value='') => String(value).replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const fmt = (v, digits=0) => Number(v ?? 0).toLocaleString(undefined,{maximumFractionDigits:digits});
const timeFmt = (v) => v ? new Date(v).toLocaleString() : '—';
const localInputValue = (date) => { const d=new Date(date); d.setMinutes(d.getMinutes()-d.getTimezoneOffset()); return d.toISOString().slice(0,16); };
const badge = (value) => { const text=String(value??'unknown'); const c=/critical|high|alarm|fault|offline|open/i.test(text)?'critical':/warning|watch|queued|investigating|scheduled|configured/i.test(text)?'warning':/normal|online|completed|operating|approved|resolved|berthed/i.test(text)?'good':''; return `<span class="badge ${c}">${escapeHtml(text.replaceAll('_',' '))}</span>`; };

async function api(path, options={}) {
  const headers = {'Content-Type':'application/json', ...(options.headers||{})};
  if (state.token) headers.Authorization = `Bearer ${state.token}`;
  const response = await fetch(`${API}${path}`, {...options, headers});
  if (response.status === 401) { logout(false); throw new Error('Session expired'); }
  if (!response.ok) { let detail; try { detail=(await response.json()).detail; } catch { detail=await response.text(); } throw new Error(typeof detail==='string'?detail:JSON.stringify(detail)); }
  const type=response.headers.get('content-type')||'';
  return type.includes('application/json') ? response.json() : response;
}
function toast(message){ const node=$('#toast'); node.textContent=message; node.classList.remove('hidden'); clearTimeout(node._t); node._t=setTimeout(()=>node.classList.add('hidden'),3500); }
function setTitle(kicker,title){ $('#section-kicker').textContent=kicker; $('#section-title').textContent=title; }
function metric(label,value,hint='',klass=''){return `<article class="metric ${klass}"><div class="label">${label}</div><div class="value">${value}</div><div class="hint">${hint}</div></article>`;}
function panel(title,body,actions=''){return `<section class="panel"><header class="panel-header"><h3>${title}</h3><div>${actions}</div></header><div class="panel-body">${body}</div></section>`;}
function lineChart(values, width=680, height=190){ if(!values.length) return '<div class="empty">No data</div>'; const min=Math.min(...values),max=Math.max(...values),spread=max-min||1; const pts=values.map((v,i)=>`${20+i*(width-40)/Math.max(values.length-1,1)},${height-20-(v-min)/spread*(height-40)}`).join(' '); return `<svg class="chart" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none"><line class="grid" x1="20" y1="20" x2="20" y2="${height-20}"/><line class="grid" x1="20" y1="${height-20}" x2="${width-20}" y2="${height-20}"/><line class="grid" x1="20" y1="${height/2}" x2="${width-20}" y2="${height/2}"/><polyline points="${pts}"/><text x="24" y="16">${max.toFixed(1)}</text><text x="24" y="${height-4}">${min.toFixed(1)}</text></svg>`; }

async function login(email,password){ const result=await api('/auth/login',{method:'POST',body:JSON.stringify({email,password})}); state.token=result.access_token; state.refreshToken=result.refresh_token; state.user=result.user; localStorage.setItem('hv-token',state.token); localStorage.setItem('hv-refresh',state.refreshToken); showApp(); }
async function restore(){ if(!state.token) return; try { state.user=await api('/auth/me'); showApp(); } catch { logout(); } }
async function logout(revoke=true){ const token=state.refreshToken; if(revoke&&token&&state.token){ try{ await api('/auth/logout',{method:'POST',body:JSON.stringify({refresh_token:token})}); }catch{/* local cleanup still applies */} } localStorage.removeItem('hv-token'); localStorage.removeItem('hv-refresh'); state.token=null; state.refreshToken=null; state.user=null; clearInterval(state.playbackTimer); if(state.eventSource)state.eventSource.close(); $('#app').classList.add('hidden'); $('#login').classList.remove('hidden'); }
function showApp(){ $('#login').classList.add('hidden'); $('#app').classList.remove('hidden'); $('#user-role').textContent=`${state.user.name || state.user.email} · ${state.user.role}`; connectEvents(); navigate(state.view); }

function connectEvents(){ if(state.eventSource)state.eventSource.close(); const connection=$('#connection'); const es=new EventSource(`${API}/events/stream?token=${encodeURIComponent(state.token)}`); state.eventSource=es; es.onopen=()=>{connection.classList.remove('offline');connection.innerHTML='<span></span>Live event stream';}; es.onerror=()=>{connection.classList.add('offline');connection.innerHTML='<span></span>Reconnecting';}; es.addEventListener('operational',e=>{ const event=JSON.parse(e.data); if(state.view==='command') prependLiveEvent(event); }); }
function prependLiveEvent(event){ const list=$('#live-events'); if(!list)return; const item=document.createElement('div'); item.className='event-item'; item.innerHTML=`<span class="event-line"></span><div><strong>${escapeHtml(event.type.replaceAll('_',' '))}</strong><p>${escapeHtml(event.entity_type)} ${escapeHtml(event.entity_id)}</p></div><time>now</time>`; list.prepend(item); }

function digitalTwinSvg(data, layerOverrides={}){
  const layers={berths:true,vessels:true,yard:true,equipment:true,cameras:true,gates:true,...state.layers,...layerOverrides};
  const blocks=layers.yard?data.yard_blocks.map(b=>{const fill=b.is_closed?'#3a2027':b.kind==='reefer'?'#123e4a':b.kind==='hazardous'?'#49351c':b.utilization>.85?'#66333a':'#12374a'; return `<g class="twin-entity" data-name="${b.code}"><rect x="${b.x}" y="${b.y}" width="${b.width}" height="${b.height}" rx="6" fill="${fill}" stroke="#2c6f83"/><text x="${b.x+10}" y="${b.y+22}" fill="#c8edf5" font-size="14" font-weight="700">${b.code}</text><text x="${b.x+10}" y="${b.y+42}" fill="#7ca7b8" font-size="11">${Math.round(b.utilization*100)}% · ${b.occupied}/${b.capacity}</text></g>`}).join(''):'';
  const berths=layers.berths?data.berths.map(b=>`<g><rect x="${b.x}" y="${b.y}" width="${b.width}" height="${b.height}" rx="4" fill="#12303e" stroke="#28728a"/><text x="${b.x+10}" y="${b.y+32}" fill="#90d5e4" font-size="13">BERTH ${b.code}</text></g>`).join(''):'';
  const vessels=layers.vessels?data.vessels.filter(v=>v.status!=='departed').map(v=>`<g><path d="M${v.x},${v.y} h150 l20,20 -20,20 h-150 z" fill="${v.status==='berthed'?'#145a65':'#33405e'}" stroke="#42d4e2"/><text x="${v.x+12}" y="${v.y+25}" fill="#e2fbff" font-size="11">${escapeHtml(v.name)}</text></g>`).join(''):'';
  const equipment=layers.equipment?data.equipment.map(e=>`<g><circle cx="${e.x}" cy="${e.y}" r="6" fill="${e.state==='maintenance'?'#ff5b68':e.state==='operating'?'#37efb3':'#ffbd4a'}"/><text x="${e.x+9}" y="${e.y+4}" fill="#6e95a8" font-size="8">${e.code}</text></g>`).join(''):'';
  const cams=layers.cameras?data.cameras.map(c=>`<g><path d="M${c.x-5},${c.y-5} h10 v10 h-10z" fill="${c.status==='online'?'#39d6e8':'#597482'}"/><path d="M${c.x+5},${c.y-3} l8,-5 v16 l-8,-5z" fill="#597482"/></g>`).join(''):'';
  const gates=layers.gates?data.gate_lanes.map(l=>`<g><rect x="${l.x}" y="${l.y}" width="22" height="32" fill="${l.is_open?'#17483d':'#44232b'}" stroke="${l.is_open?'#37efb3':'#ff5b68'}"/><text x="${l.x+3}" y="${l.y+20}" fill="#d6edf2" font-size="8">${l.code}</text>${l.queue_length?`<text x="${l.x}" y="${l.y-6}" fill="#ffbd4a" font-size="9">Q${l.queue_length}</text>`:''}</g>`).join(''):'';
  return `<div class="map-shell"><svg viewBox="0 0 1200 700" role="img" aria-label="NorthStar terminal digital twin"><rect x="0" y="0" width="1200" height="120" fill="#092a3d"/><path d="M0,115 C280,96 560,136 860,105 C1020,88 1110,100 1200,92" fill="none" stroke="#1e6981" stroke-width="4"/><text x="28" y="52" fill="#367b91" font-size="18" letter-spacing="4">NORTHSTAR APPROACH CHANNEL</text>${berths}${vessels}${blocks}<path d="M55 335 H1130 M55 565 H1010 M360 115 V620 M820 115 V620" stroke="#254654" stroke-width="18" fill="none" opacity=".75"/>${equipment}${cams}${gates}<rect x="1020" y="500" width="165" height="140" rx="8" fill="#0d2632" stroke="#245466"/><text x="1034" y="527" fill="#8fcbd8" font-size="12">GATE COMPLEX G1</text></svg><div class="map-legend"><div class="legend-item"><i class="legend-dot" style="background:#37efb3"></i>Operating equipment</div><div class="legend-item"><i class="legend-dot" style="background:#ff5b68"></i>Critical / maintenance</div><div class="legend-item"><i class="legend-dot" style="background:#123e4a"></i>Reefer zone</div><div class="legend-item"><i class="legend-dot" style="background:#49351c"></i>Hazardous zone</div></div></div>`;
}

async function renderCommand(){ setTitle('TERMINAL OPERATIONS','Executive command center'); const [d,twin]=await Promise.all([api('/dashboard'),api('/digital-twin/state')]); const k=d.kpis; $('#content').innerHTML=`<div class="metric-grid">${metric('Vessels in port',k.vessels_in_port,'Live vessel calls','good')}${metric('Berth utilization',`${k.berth_utilization_pct}%`,'Current occupied berths')}${metric('Yard occupancy',`${k.yard_occupancy_pct}%`,'Persisted stack slots',k.yard_occupancy_pct>85?'warning':'')}${metric('Gate queue',k.gate_queue,`${k.average_gate_wait_minutes} min average wait`,k.gate_queue>12?'warning':'')}${metric('Active incidents',k.active_incidents,'Requires operational review',k.active_incidents?'critical':'good')}${metric('Equipment availability',`${k.equipment_availability_pct}%`,'Fleet weighted average','good')}${metric('Reefer alarms',k.critical_reefer_alarms,'Latest sensor status',k.critical_reefer_alarms?'critical':'good')}${metric('Container registry',fmt(k.container_registry),'ISO-validated assets')}${metric('Congestion score',d.congestion.score,d.congestion.level,d.congestion.level==='normal'?'good':'warning')}${metric('Gate processed',d.gate.processed,'Deterministic seeded visits')}</div><div class="grid-2">${panel('Terminal digital twin',digitalTwinSvg(twin),'<button class="secondary" data-go="twin">Open full twin</button>')}${panel('Live operational events',`<div id="live-events" class="event-list">${d.latest_events.map(e=>`<div class="event-item"><span class="event-line"></span><div><strong>${escapeHtml(e.type.replaceAll('_',' '))}</strong><p>${escapeHtml(e.entity)} · ${escapeHtml(e.source)}</p></div><time>${new Date(e.time).toLocaleTimeString()}</time></div>`).join('')}</div>`)}</div><div class="grid-3">${panel('Congestion composition',`<div style="display:flex;gap:28px;align-items:center"><div class="gauge" style="--value:${d.congestion.score}"><div><strong>${d.congestion.score}</strong><span>${d.congestion.level}</span></div></div><div class="bar-list" style="flex:1">${Object.entries(d.congestion.components).map(([n,v])=>`<div class="bar-row"><span>${n.split('_')[0]}</span><div class="bar"><i style="width:${v*100}%"></i></div><b>${Math.round(v*100)}%</b></div>`).join('')}</div></div>`)}${panel('Gate pulse',`<div class="bar-list"><div class="bar-row"><span>Queue</span><div class="bar"><i style="width:${Math.min(d.gate.queue_length/30*100,100)}%"></i></div><b>${d.gate.queue_length}</b></div><div class="bar-row"><span>Wait</span><div class="bar"><i style="width:${Math.min(d.gate.average_wait_minutes/45*100,100)}%"></i></div><b>${d.gate.average_wait_minutes}m</b></div><div class="bar-row"><span>Service</span><div class="bar"><i style="width:${Math.min(d.gate.average_service_minutes/25*100,100)}%"></i></div><b>${d.gate.average_service_minutes}m</b></div></div>`)}${panel('Operational actions',`<div class="action-card"><div class="action-row"><div><strong>Daily operations report</strong><p>Persisted KPI summary in PDF</p></div><button class="secondary" id="daily-report">Export</button></div><div class="action-row"><div><strong>Normal operations scenario</strong><p>Ingest deterministic terminal events</p></div><button class="secondary" data-scenario="normal_operations">Run</button></div></div>`)}</div>`; wireCommonActions(); }

async function renderTwin(){
  setTitle('LIVE TERMINAL','Digital twin and historical playback');
  clearInterval(state.playbackTimer);
  const data=await api('/digital-twin/state');
  const end=new Date(); const start=new Date(end.getTime()-8*60*60*1000);
  const layerNames={berths:'Berths',vessels:'Vessels',yard:'Yard blocks',equipment:'Equipment',cameras:'Cameras',gates:'Gate lanes'};
  $('#content').innerHTML=`${panel('NorthStar terminal operational state',`<div id="twin-map">${digitalTwinSvg(data)}</div>`,'<div class="toolbar"><button class="secondary" id="snapshot">Create snapshot</button><button class="secondary" id="live-mode">Live state</button></div>')}<div class="grid-3">${panel('Operational layers',`<div class="action-card">${Object.entries(layerNames).map(([key,label])=>`<label class="action-row"><strong>${label}</strong><input class="layer-toggle" data-layer="${key}" type="checkbox" ${state.layers[key]===false?'':'checked'} style="width:auto"/></label>`).join('')}</div>`)}${panel('Historical playback',`<div class="playback-controls"><label>Start<input id="playback-start" type="datetime-local" value="${localInputValue(start)}"/></label><label>End<input id="playback-end" type="datetime-local" value="${localInputValue(end)}"/></label><div class="toolbar"><button class="primary" id="load-playback">Load events</button><button class="secondary" id="play-playback" disabled>Play</button><button class="secondary" id="pause-playback" disabled>Pause</button><select id="playback-speed"><option value="1200">1×</option><option value="600">2×</option><option value="240">5×</option></select></div><input id="playback-slider" type="range" min="0" max="0" value="0" disabled/><div id="playback-status" class="notice">Select a persisted time window. Replay uses the nearest snapshot plus ordered operational events.</div></div>`)}${panel('Terminal geometry',`<table><tr><th>Coordinate system</th><td>${escapeHtml(data.terminal.geometry.coordinate_system)}</td></tr><tr><th>Extent</th><td>${data.terminal.geometry.extent.join(' × ')}</td></tr><tr><th>Origin</th><td>${escapeHtml(data.terminal.geometry.origin)}</td></tr><tr><th>State mode</th><td>${badge(data.mode)}</td></tr><tr><th>Updated</th><td>${timeFmt(data.generated_at)}</td></tr></table><div id="playback-event" class="event-detail"><div class="empty">No historical frame selected.</div></div>`)}</div>`;
  $('#snapshot').onclick=async()=>{const r=await api('/digital-twin/snapshot',{method:'POST'});toast(`Snapshot ${r.id} created from ${r.event_count} events`)};
  $('#live-mode').onclick=renderTwin;
  document.querySelectorAll('.layer-toggle').forEach(node=>node.onchange=()=>{state.layers[node.dataset.layer]=node.checked;localStorage.setItem('hv-layers',JSON.stringify(state.layers));$('#twin-map').innerHTML=digitalTwinSvg(data);});
  $('#load-playback').onclick=loadPlayback;
  $('#play-playback').onclick=playPlayback;
  $('#pause-playback').onclick=()=>clearInterval(state.playbackTimer);
  $('#playback-slider').oninput=e=>showPlaybackFrame(Number(e.target.value));
}

async function loadPlayback(){
  clearInterval(state.playbackTimer);
  const start=new Date($('#playback-start').value); const end=new Date($('#playback-end').value);
  if(!start.getTime()||!end.getTime()||end<=start){toast('Playback end must be after start');return;}
  $('#playback-status').textContent='Loading persisted events and nearest snapshot…';
  const result=await api(`/digital-twin/playback?start=${encodeURIComponent(start.toISOString())}&end=${encodeURIComponent(end.toISOString())}&limit=500`);
  state.playback=result;
  const slider=$('#playback-slider'); slider.max=Math.max(result.frames.length-1,0);slider.value=0;slider.disabled=!result.frames.length;
  $('#play-playback').disabled=!result.frames.length;$('#pause-playback').disabled=!result.frames.length;
  $('#playback-status').innerHTML=`${result.event_count} event(s) · ${escapeHtml(result.reconstruction)}${result.truncated?' · window truncated':''}`;
  if(result.frames.length)showPlaybackFrame(0);else $('#playback-event').innerHTML='<div class="empty">No operational events in the selected window.</div>';
}

function showPlaybackFrame(index){
  if(!state.playback?.frames?.length)return;
  const frame=state.playback.frames[Math.max(0,Math.min(index,state.playback.frames.length-1))];
  $('#playback-slider').value=index;
  $('#playback-event').innerHTML=`<div class="event-item"><span class="event-line"></span><div><strong>${escapeHtml(frame.event.event_type.replaceAll('_',' '))}</strong><p>${escapeHtml(frame.event.entity_type)} ${escapeHtml(frame.event.entity_id)} · ${escapeHtml(frame.event.processing_status)}</p></div><time>${timeFmt(frame.at)}</time></div><table><tr><th>Source</th><td>${escapeHtml(frame.event.source)}</td></tr><tr><th>Correlation</th><td>${escapeHtml(frame.event.correlation_id)}</td></tr><tr><th>State delta</th><td><pre>${escapeHtml(JSON.stringify(frame.delta.state,null,2))}</pre></td></tr></table>`;
}

function playPlayback(){
  clearInterval(state.playbackTimer);
  if(!state.playback?.frames?.length)return;
  const delay=Number($('#playback-speed').value||1200);
  state.playbackTimer=setInterval(()=>{const slider=$('#playback-slider');const next=Number(slider.value)+1;if(next>=state.playback.frames.length){clearInterval(state.playbackTimer);return;}showPlaybackFrame(next);},delay);
}

async function renderVessels(){ setTitle('BERTH & MARINE','Vessel operations'); const [vessels,berths]=await Promise.all([api('/vessels'),api('/berths')]); $('#content').innerHTML=`<div class="metric-grid">${metric('Calls',vessels.length,'Current planning horizon')}${metric('At berth',vessels.filter(v=>['berthed','operations'].includes(v.status)).length,'Active operations','good')}${metric('Approaching',vessels.filter(v=>v.status==='approaching').length,'ETA tracked')}${metric('Total target moves',fmt(vessels.reduce((a,v)=>a+v.target_moves,0)),'Across vessel calls')}${metric('Completed moves',fmt(vessels.reduce((a,v)=>a+v.actual_moves,0)),'Persisted production')}</div><div class="grid-2">${panel('Berth planning board',`<div class="table-wrap"><table><thead><tr><th>Vessel</th><th>Voyage</th><th>Status</th><th>Berth</th><th>Planned start</th><th>Planned end</th><th>Moves</th></tr></thead><tbody>${vessels.map(v=>`<tr><td><strong>${escapeHtml(v.name)}</strong><br><small>${v.imo}</small></td><td>${v.voyage}</td><td>${badge(v.status)}</td><td>${berths.find(b=>b.id===v.berth_id)?.code||'—'}</td><td>${timeFmt(v.planned_start)}</td><td>${timeFmt(v.planned_end)}</td><td>${v.actual_moves}/${v.target_moves}</td></tr>`).join('')}</tbody></table></div>`)}${panel('Schedule integrity',`<div class="notice">Berth assignments are validated server-side. Overlapping windows on the same berth return a conflict with the affected vessel call.</div><div class="bar-list" style="margin-top:20px">${berths.map(b=>{const active=vessels.filter(v=>v.berth_id===b.id&&v.status!=='departed').length;return `<div class="bar-row"><span>${b.code}</span><div class="bar"><i style="width:${Math.min(active*50,100)}%"></i></div><b>${active}</b></div>`}).join('')}</div>`)}</div>`; }

async function renderYard(){ setTitle('YARD CONTROL','Stack intelligence and slot planning'); const blocks=await api('/yard/blocks'); $('#content').innerHTML=`<div class="metric-grid">${metric('Yard blocks',blocks.length,'General, reefer and hazardous')}${metric('Occupied slots',fmt(blocks.reduce((a,b)=>a+b.occupied,0)),'Physical slots')}${metric('Available slots',fmt(blocks.reduce((a,b)=>a+b.capacity-b.occupied,0)),'Placement capacity','good')}${metric('Highest utilization',`${Math.round(Math.max(...blocks.map(b=>b.utilization))*100)}%`,'Block saturation')}${metric('Special zones',blocks.filter(b=>b.kind!=='general').length,'Segregated capacity')}</div><div class="grid-2">${panel('Block utilization',`<div class="bar-list">${blocks.map(b=>`<div class="bar-row" style="grid-template-columns:70px 1fr 70px"><button class="secondary block-open" data-block="${b.id}">${b.code}</button><div class="bar"><i style="width:${b.utilization*100}%"></i></div><b>${Math.round(b.utilization*100)}%</b></div>`).join('')}</div>`)}${panel('Placement rules',`<div class="action-card"><div class="action-row"><div><strong>Reefer compatibility</strong><p>Powered R1 slots only</p></div>${badge('enforced')}</div><div class="action-row"><div><strong>Hazardous segregation</strong><p>H1 restricted placement</p></div>${badge('enforced')}</div><div class="action-row"><div><strong>Rehandle penalty</strong><p>Tier and retrieval priority scoring</p></div>${badge('calculated')}</div><div class="action-row"><div><strong>Capacity pressure</strong><p>Utilization-weighted recommendation</p></div>${badge('calculated')}</div></div>`)}</div><div id="block-detail" style="margin-top:14px"></div>`; document.querySelectorAll('.block-open').forEach(btn=>btn.onclick=()=>loadBlock(btn.dataset.block)); }
async function loadBlock(id){ const data=await api(`/yard/blocks/${id}`); const occupied=data.slots.filter(s=>s.occupied); $('#block-detail').innerHTML=panel(`${data.block.code} stack slots`, `<div class="notice">${data.block.kind.toUpperCase()} block · ${occupied.length}/${data.block.capacity} occupied. Each cell represents a physical bay/row/tier slot.</div><div class="stack-grid" style="margin-top:15px">${data.slots.map(s=>`<div class="slot ${s.occupied?'occupied':''} ${s.container?.is_reefer?'reefer':''} ${s.container?.is_hazardous?'hazardous':''}" title="Bay ${s.bay} Row ${s.row} Tier ${s.tier}${s.container?' · '+s.container.number:''}">${s.occupied?s.tier:'·'}</div>`).join('')}</div>`); }

async function renderContainers(){ setTitle('CONTAINER FLOW','Registry, traceability and placement'); $('#content').innerHTML=`${panel('Container search',`<div class="toolbar"><input id="container-q" placeholder="Full or partial container number"/><select id="container-filter"><option value="">All cargo flows</option><option>import</option><option>export</option><option>transshipment</option></select><button class="primary" id="container-search">Search</button><button class="secondary" id="csv-export">Export CSV</button></div><div id="container-results" class="table-wrap" style="margin-top:12px"></div>`)}<div id="container-detail" style="margin-top:14px"></div>`; $('#container-search').onclick=searchContainers; $('#container-q').onkeydown=e=>{if(e.key==='Enter')searchContainers()}; $('#csv-export').onclick=()=>downloadAuthorized('/reports/containers.csv','containers.csv'); await searchContainers(); }
async function searchContainers(){ const q=encodeURIComponent($('#container-q').value||''); const movement=encodeURIComponent($('#container-filter').value||''); const data=await api(`/containers?q=${q}&movement_type=${movement}&limit=40`); $('#container-results').innerHTML=`<table><thead><tr><th>Container</th><th>Location</th><th>Flow</th><th>Type</th><th>Status</th><th>Dwell start</th><th>Flags</th></tr></thead><tbody>${data.items.map(c=>`<tr class="container-open" data-id="${c.id}"><td><strong>${c.number}</strong><br><small>${c.validation.valid?'ISO valid':'invalid'}</small></td><td>${c.location?`${c.location.block} / ${c.location.bay}-${c.location.row}-${c.location.tier}`:'—'}</td><td>${c.movement_type}</td><td>${c.iso_type}</td><td>${badge(c.status)}</td><td>${timeFmt(c.dwell_start)}</td><td>${c.is_reefer?badge('reefer'):''} ${c.is_hazardous?badge('hazardous'):''}</td></tr>`).join('')}</tbody></table><p class="muted">Showing ${data.items.length} of ${data.total} records</p>`; document.querySelectorAll('.container-open').forEach(r=>r.onclick=()=>openContainer(r.dataset.id)); }
async function openContainer(id){ const [c,recs]=await Promise.all([api(`/containers/${id}`),api(`/containers/${id}/recommendations`)]); $('#container-detail').innerHTML=`<div class="grid-2">${panel(`${c.number} · Container detail`,`<div class="metric-grid" style="grid-template-columns:repeat(3,1fr)">${metric('Status',c.status,'Persisted state')}${metric('Location',c.location?`${c.location.block} ${c.location.bay}-${c.location.row}-${c.location.tier}`:'Off-yard','Current slot')}${metric('Weight',`${fmt(c.weight_kg)} kg`,'Declared gross')}${metric('Flow',c.movement_type,'Import/export direction')}${metric('ISO validation',c.validation.valid?'Valid':'Invalid',`Expected digit ${c.validation.expected_check_digit}`,c.validation.valid?'good':'critical')}${metric('Last movement',new Date(c.last_movement_at).toLocaleDateString(),'Traceable event')}</div><div class="timeline" style="margin-top:18px">${c.movements.slice(0,5).map(m=>`<div class="step"><strong>${m.type.replaceAll('_',' ')}</strong><span>${new Date(m.occurred_at).toLocaleDateString()}</span></div>`).join('')||'<span class="muted">No movements</span>'}</div>`)}${panel('Explainable slot recommendations',`<div class="action-card">${recs.map(r=>`<div class="action-row"><div><strong>${r.block_code} · Bay ${r.bay} / Row ${r.row} / Tier ${r.tier}</strong><p>${r.explanation.join(' · ')}</p></div><span class="badge good">score ${r.score}</span></div>`).join('')||'<div class="empty">No compatible free slot</div>'}</div>`)}</div>`; }

async function renderGate(){ setTitle('LANDSIDE FLOW','Gate and truck operations'); const d=await api('/gates/overview'); $('#content').innerHTML=`<div class="metric-grid">${metric('Current queue',d.queue_length,'Queued + processing',d.queue_length>12?'warning':'')}${metric('Average wait',`${d.average_wait_minutes} min`,'Arrival to processing')}${metric('Service time',`${d.average_service_minutes} min`,'Processing window')}${metric('Open lanes',d.open_lanes,'Available capacity','good')}${metric('Processed visits',d.processed,'Seeded operating history')}</div>${panel('Latest truck visits',`<div class="table-wrap"><table><thead><tr><th>Plate</th><th>Driver</th><th>Status</th><th>Lane</th><th>Arrival</th><th>Processing</th><th>Exit</th></tr></thead><tbody>${d.visits.map(v=>`<tr><td><strong>${v.plate}</strong></td><td>${v.driver}</td><td>${badge(v.status)}</td><td>${v.lane_id}</td><td>${timeFmt(v.arrival_at)}</td><td>${timeFmt(v.processing_start)}</td><td>${timeFmt(v.exit_at)}</td></tr>`).join('')}</tbody></table></div>`,'<button class="secondary" data-scenario="gate_congestion">Simulate congestion</button>')} `; wireCommonActions(); }

async function renderSafety(){ setTitle('SAFETY OPERATIONS','Video intelligence and incident control'); const [events,incidents,jobs]=await Promise.all([api('/safety-events'),api('/incidents'),api('/ocr/jobs')]); $('#content').innerHTML=`<div class="metric-grid">${metric('Safety detections',events.length,'Persisted computer-vision events',events.length?'warning':'good')}${metric('Unreviewed',events.filter(e=>e.review_status==='unreviewed').length,'Evidence awaiting review')}${metric('Active incidents',incidents.filter(i=>!['resolved','dismissed'].includes(i.status)).length,'Operational workflow',incidents.length?'critical':'good')}${metric('OCR jobs',jobs.length,'Container-code pipeline')}${metric('Camera baseline','MOG2 + tracker','CPU-first verified')}</div><div class="grid-2">${panel('Safety event center',events.length?`<div class="event-list">${events.map(e=>`<div class="event-item"><span class="event-line" style="background:#ff5b68"></span><div><strong>${e.event_type.replaceAll('_',' ')} · Track ${e.track_id}</strong><p>${badge(e.severity)} confidence ${Math.round(e.confidence*100)}% · ${timeFmt(e.detected_at)}</p>${e.evidence_url?`<a href="${e.evidence_url}" target="_blank" style="color:var(--cyan);font-size:11px">Open evidence</a>`:''}</div><time>${e.review_status}</time></div>`).join('')}</div>`:'<div class="empty">Process the included video to create a real event.</div>','<button class="primary" id="process-video">Process sample video</button>')}${panel('Incident workflow',`<div class="action-card">${incidents.map(i=>`<div class="action-row"><div><strong>${escapeHtml(i.title)}</strong><p>${i.type.replaceAll('_',' ')} · ${i.assigned_to||'Unassigned'} · ${timeFmt(i.created_at)}</p></div><div>${badge(i.severity)} ${badge(i.status)}</div></div>`).join('')||'<div class="empty">No incidents</div>'}</div>`)}</div><div class="grid-2">${panel('Container OCR review',jobs.length?`<table><thead><tr><th>Raw OCR</th><th>Candidate</th><th>Confidence</th><th>Status</th></tr></thead><tbody>${jobs.map(j=>`<tr><td>${escapeHtml(j.raw_text)}</td><td><strong>${j.normalized_number||'—'}</strong></td><td>${Math.round(j.confidence*100)}%</td><td>${badge(j.validation_status)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No OCR results yet</div>','<button class="secondary" id="process-ocr">Run OCR sample</button>')}${panel('Verified safety pipeline',`<div class="timeline"><div class="step"><strong>Frame ingest</strong><span>MP4 / timestamps</span></div><div class="step"><strong>MOG2 motion</strong><span>Real contours</span></div><div class="step"><strong>Centroid tracker</strong><span>Track IDs</span></div><div class="step"><strong>Polygon rule</strong><span>Dwell + cooldown</span></div><div class="step"><strong>Evidence</strong><span>Annotated JPEG</span></div></div><div class="notice" style="margin-top:16px">The mandatory demo does not claim PPE or person-class semantics. It verifies motion-derived tracked-object intrusion using actual video frames.</div>`)}</div>`; $('#process-video').onclick=async()=>{toast('Processing CPU video frames…');const r=await api('/vision/process-sample',{method:'POST'});toast(`${r.frames_processed} frames processed; ${r.events_created} safety event(s)`);renderSafety()}; $('#process-ocr').onclick=async()=>{const r=await api('/ocr/process-sample',{method:'POST'});toast(`OCR ${r.validation_status}: ${r.normalized_number||r.raw_text}`);renderSafety()}; }

async function renderEquipment(){ setTitle('ASSET RELIABILITY','Equipment fleet and predictive indicators'); const items=await api('/equipment'); $('#content').innerHTML=`<div class="metric-grid">${metric('Fleet assets',items.length,'Cranes and yard equipment')}${metric('Operating',items.filter(x=>x.state==='operating').length,'Current state','good')}${metric('Maintenance',items.filter(x=>x.state==='maintenance').length,'Unavailable assets',items.some(x=>x.state==='maintenance')?'critical':'')}${metric('High risk',items.filter(x=>['high','critical'].includes(x.risk.severity)).length,'Telemetry risk indicators','warning')}${metric('Average availability',`${fmt(items.reduce((a,x)=>a+x.availability,0)/items.length*100,1)}%`,'Persisted fleet measure')}</div>${panel('Fleet health',`<div class="table-wrap"><table><thead><tr><th>Asset</th><th>Type</th><th>State</th><th>Availability</th><th>Temperature</th><th>Vibration</th><th>Risk</th><th>Explanation</th></tr></thead><tbody>${items.map(x=>`<tr class="equipment-open" data-id="${x.id}"><td><strong>${x.code}</strong><br>${x.name}</td><td>${x.type}</td><td>${badge(x.state)}</td><td>${Math.round(x.availability*100)}%</td><td>${x.latest?.temperature_c??'—'} °C</td><td>${x.latest?.vibration_mm_s??'—'} mm/s</td><td>${badge(x.risk.severity)} ${x.risk.score}</td><td style="white-space:normal;min-width:270px">${escapeHtml(x.risk.explanation)}</td></tr>`).join('')}</tbody></table></div>`,'<button class="secondary" data-scenario="equipment_anomaly">Inject deterministic anomaly</button>')}<div id="equipment-detail" style="margin-top:14px"></div>`; document.querySelectorAll('.equipment-open').forEach(r=>r.onclick=()=>openEquipment(r.dataset.id)); wireCommonActions(); }
async function openEquipment(id){const d=await api(`/equipment/${id}`); $('#equipment-detail').innerHTML=`<div class="grid-2">${panel(`${d.equipment.code} telemetry`,lineChart(d.telemetry.map(x=>x.temperature_c)))}${panel('Risk interpretation',`<div class="metric ${d.risk.severity==='normal'?'good':'warning'}"><div class="label">Engineering risk indicator</div><div class="value">${d.risk.score}</div><div class="hint">${escapeHtml(d.risk.explanation)}</div></div><div class="notice" style="margin-top:12px">${escapeHtml(d.risk.suggested_action)}. This is an anomaly indicator, not a certified failure prediction.</div>`)}</div>`; }

async function renderReefers(){ setTitle('COLD CHAIN','Reefer monitoring and escalation'); const items=await api('/reefers'); $('#content').innerHTML=`<div class="metric-grid">${metric('Reefer containers',items.length,'Powered inventory')}${metric('Compliant',items.filter(x=>x.alarm_state==='normal').length,'Latest readings','good')}${metric('Active alarms',items.filter(x=>x.alarm_state!=='normal').length,'Requires attention',items.some(x=>x.alarm_state!=='normal')?'critical':'good')}${metric('Power losses',items.filter(x=>!x.power_on).length,'Latest telemetry')}${metric('Max deviation',`${fmt(Math.max(...items.map(x=>Math.abs(x.deviation_c))),1)} °C`,'From target')}</div>${panel('Reefer exception board',`<div class="table-wrap"><table><thead><tr><th>Container</th><th>Target</th><th>Actual</th><th>Deviation</th><th>Power</th><th>Door</th><th>Alarm</th><th>Last reading</th></tr></thead><tbody>${items.map(x=>`<tr><td><strong>${x.number}</strong></td><td>${x.target_c} °C</td><td>${x.actual_c} °C</td><td class="${Math.abs(x.deviation_c)>2?'severity-high':''}">${x.deviation_c>0?'+':''}${x.deviation_c} °C</td><td>${badge(x.power_on?'on':'off')}</td><td>${badge(x.door_open?'open':'closed')}</td><td>${badge(x.alarm_state)}</td><td>${timeFmt(x.last_reading)}</td></tr>`).join('')}</tbody></table></div>`,'<button class="secondary" data-scenario="reefer_deviation">Simulate deviation</button>')} `; wireCommonActions(); }

async function renderAnalytics(){ setTitle('PERFORMANCE INTELLIGENCE','Terminal KPI analytics'); const k=await api('/analytics/kpis'); const keys=Object.entries(k).filter(([key])=>key!=='source'); $('#content').innerHTML=`<div class="metric-grid">${metric('Vessel turnaround',`${k.vessel_turnaround_hours} h`,'Actual departure minus arrival')}${metric('Yard utilization',`${k.yard_utilization_pct}%`,'Physical occupied slots')}${metric('Container dwell',`${k.container_dwell_days} d`,'Registry average')}${metric('Truck turnaround',`${k.truck_turnaround_minutes} min`,'Arrival to exit')}${metric('Crane production',`${k.crane_moves_per_hour} moves/h`,'Actual moves / planned operation hours')}${metric('Gate throughput',fmt(k.gate_throughput),'Completed transactions')}${metric('Equipment availability',`${k.equipment_availability_pct}%`,'Fleet average','good')}${metric('Reefer compliance',`${k.reefer_compliance_pct}%`,'Latest readings',k.reefer_compliance_pct<95?'warning':'good')}${metric('Appointment compliance',`${k.appointment_compliance_pct}%`,'Within ±15 minutes')}${metric('Incident rate',k.active_incident_rate_per_1000_moves,'Active per 1,000 moves')}</div><div class="grid-2">${panel('KPI provenance',`<div class="notice">${escapeHtml(k.source)}. Values change after simulation scenarios because the same persistence and business logic are used.</div><table style="margin-top:15px">${keys.map(([n,v])=>`<tr><th>${n.replaceAll('_',' ')}</th><td>${v}</td></tr>`).join('')}</table>`)}${panel('Exports',`<div class="action-card"><div class="action-row"><div><strong>Daily terminal report</strong><p>Calculated KPI PDF</p></div><button class="secondary" id="daily-report">PDF</button></div><div class="action-row"><div><strong>Container registry</strong><p>Filtered operational export</p></div><button class="secondary" id="container-csv">CSV</button></div><div class="action-row"><div><strong>Daily summary</strong><p>Machine-readable result</p></div><button class="secondary" id="daily-json">JSON</button></div></div>`)}</div>`; $('#daily-report').onclick=()=>downloadAuthorized('/reports/daily.pdf','daily-terminal-operations.pdf'); $('#container-csv').onclick=()=>downloadAuthorized('/reports/containers.csv','containers.csv'); $('#daily-json').onclick=async()=>{const d=await api('/reports/daily.json');const blob=new Blob([JSON.stringify(d,null,2)],{type:'application/json'});downloadBlob(blob,'daily-terminal-operations.json')}; }

async function renderDataset(){
  setTitle('PUBLIC DATASET','NGA World Port Index sample');
  const data=await api('/public-dataset/ports?limit=40');
  const s=data.summary;
  const coverage=Object.entries(s.service_coverage).map(([name,value])=>`<div class="bar-row"><span>${escapeHtml(name)}</span><div class="bar"><i style="width:${value}%"></i></div><b>${value}%</b></div>`).join('');
  const maxCountry=Math.max(...s.top_countries.map(c=>c.ports),1);
  const countries=s.top_countries.map(x=>`<div class="bar-row"><span>${escapeHtml(x.country)}</span><div class="bar"><i style="width:${Math.min(x.ports/maxCountry*100,100)}%"></i></div><b>${x.ports}</b></div>`).join('');
  $('#content').innerHTML=`<div class="metric-grid">${metric('Sample ports',s.sample_ports,'Processed public-domain WPI records','good')}${metric('Countries',s.countries,'Distinct country codes')}${metric('Large harbors',s.large_harbors,'WPI harbor size L')}${metric('Medium harbors',s.medium_harbors,'WPI harbor size M')}${metric('Avg readiness',`${s.average_readiness_score}/100`,'Derived service-coverage score')}</div><div class="grid-2">${panel('Dataset provenance',`<table><tr><th>Dataset</th><td>${escapeHtml(data.dataset.title)}</td></tr><tr><th>Publisher</th><td>${escapeHtml(data.dataset.publisher)}</td></tr><tr><th>License</th><td>${escapeHtml(data.dataset.license)}</td></tr><tr><th>Sample file</th><td><code>${escapeHtml(data.dataset.sample_path)}</code></td></tr></table><div class="notice" style="margin-top:12px">${escapeHtml(data.dataset.label)}</div>`)}${panel('Service coverage in sample',`<div class="bar-list">${coverage}</div>`)}</div><div class="grid-2">${panel('Top represented countries',`<div class="bar-list">${countries}</div>`)}${panel('Harbor-size mix',`<pre>${escapeHtml(JSON.stringify(s.harbor_size_counts,null,2))}</pre>`)}</div>${panel('Ranked WPI port references',`<div class="table-wrap"><table><thead><tr><th>WPI</th><th>Port</th><th>Country</th><th>Harbor</th><th>Depth</th><th>Services</th><th>Score</th></tr></thead><tbody>${data.ports.map(p=>`<tr><td>${escapeHtml(p.wpi_number)}</td><td><strong>${escapeHtml(p.port_name)}</strong><br><small>${fmt(p.latitude,3)}, ${fmt(p.longitude,3)}</small></td><td>${escapeHtml(p.country)}</td><td>${escapeHtml(p.harbor_size||'—')} / ${escapeHtml(p.harbor_type||'—')}</td><td>${escapeHtml(p.channel_depth_code||'—')} / ${escapeHtml(p.cargo_depth_code||'—')}</td><td>${badge(`pilot ${p.pilot_available||'n/a'}`)} ${badge(`tug ${p.tug_assist||'n/a'}`)} ${badge(`rail ${p.rail||'n/a'}`)} ${badge(`diesel ${p.diesel||'n/a'}`)}</td><td><strong>${p.readiness_score}</strong></td></tr>`).join('')}</tbody></table></div>`)}`;
}

async function renderSimulation(){
  setTitle('DETERMINISTIC LAB','Scenario simulation control');
  const scenarios=await api('/simulation/scenarios');
  const descriptions={normal_operations:'Vessel and container flow through the event engine.',gate_congestion:'Adds queued truck arrivals and an operational incident.',yard_capacity_risk:'Reserves free slots and raises a capacity warning.',safety_intrusion:'Creates the event request; run video processing for evidence.',equipment_anomaly:'Adds rising temperature/vibration telemetry and a work order.',reefer_deviation:'Adds a prolonged temperature deviation and incident.'};
  $('#content').innerHTML=`<div class="grid-2">${panel('Persisted simulation run',`<form id="simulation-form" class="action-card"><label>Scenario<select id="simulation-scenario">${scenarios.map(s=>`<option value="${s}">${s.replaceAll('_',' ')}</option>`).join('')}</select></label><div class="grid-2" style="margin:0"><label>Speed multiplier<input id="simulation-speed" type="number" min="0.1" max="100" step="0.1" value="10"></label><label>Deterministic seed<input id="simulation-seed" type="number" value="20260719"></label></div><button class="primary" type="submit">Create run</button></form><div id="simulation-run" class="notice" style="margin-top:14px">Create a run to activate lifecycle controls.</div>`)}${panel('Simulation contract',`<div class="timeline"><div class="step"><strong>Fixed seed</strong><span>Repeatable inputs</span></div><div class="step"><strong>Production path</strong><span>Domain validation and event engine</span></div><div class="step"><strong>Persisted lifecycle</strong><span>Created, running, paused, completed or failed</span></div><div class="step"><strong>Operational state</strong><span>Simulated time and event count</span></div></div><div class="notice" style="margin-top:16px">Advance executes one deterministic scenario batch through the same services, validation and persistence used by normal operations.</div>`)}</div>${panel('Scenario library',`<div class="grid-3" style="margin:0">${scenarios.map(s=>`<article class="action-row report-card"><div><p class="eyebrow">SCENARIO</p><strong>${s.replaceAll('_',' ')}</strong><p>${descriptions[s]}</p></div><button class="secondary select-scenario" data-scenario="${s}">Select</button></article>`).join('')}</div>`)}<div class="grid-2">${panel('CPU vision lab',`<div class="action-card"><div class="action-row"><div><strong>Restricted-zone MP4</strong><p>MOG2, confirmed centroid tracks, polygon dwell and evidence chain</p></div><button class="secondary" id="sim-video">Process</button></div></div>`)}${panel('Container OCR lab',`<div class="action-card"><div class="action-row"><div><strong>ISO 6346 sample</strong><p>OpenCV preprocessing, Tesseract adapter, candidate ranking and validation</p></div><button class="secondary" id="sim-ocr">Process</button></div></div>`)}</div><div id="scenario-result" style="margin-top:14px"></div>`;
  let currentRun=null;
  const renderRun=()=>{
    const node=$('#simulation-run');
    if(!currentRun){node.className='notice';node.textContent='Create a run to activate lifecycle controls.';return;}
    const allowed={created:['start','reset'],running:['pause','advance','reset'],paused:['resume','reset'],completed:['reset'],failed:['reset']}[currentRun.status]||[];
    node.className='panel-body simulation-run-card';
    node.innerHTML=`<div class="metric-grid">${metric('Run',`#${currentRun.id}`,currentRun.scenario)}${metric('Status',currentRun.status,'Persisted lifecycle',currentRun.status==='failed'?'critical':currentRun.status==='completed'?'good':'warning')}${metric('Events',currentRun.event_count||0,'Accepted operational events')}${metric('Simulated time',currentRun.simulated_time?timeFmt(currentRun.simulated_time):'—','Scenario clock')}</div>${currentRun.error?`<div class="notice" style="border-color:var(--red)">${escapeHtml(currentRun.error)}</div>`:''}<div class="toolbar">${allowed.map(action=>`<button class="${action==='advance'?'primary':'secondary'} simulation-action" data-action="${action}">${action}</button>`).join('')}</div>`;
    document.querySelectorAll('.simulation-action').forEach(button=>button.onclick=async()=>{button.disabled=true;try{currentRun=await api(`/simulation/runs/${currentRun.id}/${button.dataset.action}`,{method:'POST'});renderRun();toast(`Simulation ${button.dataset.action}: ${currentRun.status}`);}catch(error){toast(error.message);button.disabled=false;}});
  };
  $('#simulation-form').onsubmit=async event=>{event.preventDefault();currentRun=await api('/simulation/runs',{method:'POST',body:JSON.stringify({scenario:$('#simulation-scenario').value,speed_multiplier:Number($('#simulation-speed').value),random_seed:Number($('#simulation-seed').value)})});renderRun();toast(`Simulation run #${currentRun.id} created`);};
  document.querySelectorAll('.select-scenario').forEach(button=>button.onclick=()=>{$('#simulation-scenario').value=button.dataset.scenario;$('#simulation-scenario').focus();toast(`${button.dataset.scenario.replaceAll('_',' ')} selected`);});
  $('#sim-video').onclick=async()=>{$('#scenario-result').innerHTML=panel('Processing','<div class="notice">CPU video analytics running on the included MP4…</div>');const r=await api('/vision/process-sample',{method:'POST'});$('#scenario-result').innerHTML=panel('Video verification',`<pre>${escapeHtml(JSON.stringify(r,null,2))}</pre>`)};
  $('#sim-ocr').onclick=async()=>{$('#scenario-result').innerHTML=panel('Processing','<div class="notice">CPU OCR pipeline running on the generated sample…</div>');const r=await api('/ocr/process-sample',{method:'POST'});$('#scenario-result').innerHTML=panel('OCR verification',`<pre>${escapeHtml(JSON.stringify(r,null,2))}</pre>`)};
}

async function renderIncidents(){
  setTitle('SAFETY GOVERNANCE','Incident management');
  const items=await api('/incidents');
  $('#content').innerHTML=`<div class="metric-grid">${metric('Open',items.filter(x=>x.status==='open').length,'New incidents')}${metric('Investigating',items.filter(x=>['acknowledged','investigating','action_required'].includes(x.status)).length,'Active workflow','warning')}${metric('Overdue',items.filter(x=>x.due_at&&new Date(x.due_at)<new Date()&&!['resolved','dismissed'].includes(x.status)).length,'Past due','critical')}${metric('Resolved',items.filter(x=>x.status==='resolved').length,'Closed with action','good')}</div>${panel('Incident register',items.length?`<div class="table-wrap"><table><thead><tr><th>ID</th><th>Incident</th><th>Severity</th><th>Status</th><th>Team</th><th>Due</th><th></th></tr></thead><tbody>${items.map(x=>`<tr><td>#${x.id}</td><td><strong>${escapeHtml(x.title)}</strong><br><small>${escapeHtml(x.type)}</small></td><td>${badge(x.severity)}</td><td>${badge(x.status)}</td><td>${escapeHtml(x.assigned_team||x.assigned_to||'Unassigned')}</td><td>${timeFmt(x.due_at)}</td><td><button class="secondary incident-open" data-id="${x.id}">Inspect</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No incidents match this organization.</div>')}<div id="incident-detail" style="margin-top:14px"></div>`;
  document.querySelectorAll('.incident-open').forEach(button=>button.onclick=()=>openIncident(Number(button.dataset.id)));
}

async function openIncident(id){
  const item=await api(`/incidents/${id}`);
  const transitions={open:['acknowledged','dismissed'],acknowledged:['investigating','dismissed'],investigating:['action_required','resolved','dismissed'],action_required:['resolved'],resolved:['open'],dismissed:['open']}[item.status]||[];
  $('#incident-detail').innerHTML=panel(`Incident #${item.id}`,`<div class="grid-2" style="margin:0"><div><div class="notice"><strong>${escapeHtml(item.title)}</strong><br>${badge(item.severity)} ${badge(item.status)}</div><table style="margin-top:12px"><tr><th>Type</th><td>${escapeHtml(item.type)}</td></tr><tr><th>Team</th><td>${escapeHtml(item.assigned_team||'Unassigned')}</td></tr><tr><th>Created</th><td>${timeFmt(item.created_at)}</td></tr><tr><th>Root cause</th><td>${escapeHtml(item.root_cause||'Not recorded')}</td></tr><tr><th>Corrective action</th><td>${escapeHtml(item.corrective_action||'Not recorded')}</td></tr></table><div class="toolbar" style="margin-top:12px">${transitions.map(status=>`<button class="secondary incident-transition" data-status="${status}">${status.replaceAll('_',' ')}</button>`).join('')}</div></div><div><h4>Attributed notes</h4><div class="event-list">${item.notes.length?item.notes.map(n=>`<div class="event-item"><span class="event-line"></span><div><strong>User ${n.user_id||'system'}</strong><p>${escapeHtml(n.note)}</p></div><time>${timeFmt(n.created_at)}</time></div>`).join(''):'<div class="empty">No notes yet.</div>'}</div><form id="incident-note-form" style="margin-top:12px"><label>Add operational note<textarea id="incident-note" rows="3" required></textarea></label><button class="primary" type="submit">Add note</button></form></div></div>`);
  document.querySelectorAll('.incident-transition').forEach(button=>button.onclick=async()=>{const status=button.dataset.status;const dismissed_reason=status==='dismissed'?prompt('Dismissal reason is required'):null;await api(`/incidents/${id}/transition`,{method:'POST',body:JSON.stringify({status,dismissed_reason})});toast(`Incident moved to ${status.replaceAll('_',' ')}`);openIncident(id)});
  $('#incident-note-form').onsubmit=async event=>{event.preventDefault();await api(`/incidents/${id}/notes`,{method:'POST',body:JSON.stringify({note:$('#incident-note').value})});toast('Incident note added');openIncident(id)};
}

async function renderWorkOrders(){
  setTitle('MAINTENANCE CONTROL','Work-order management');
  const items=await api('/work-orders');
  $('#content').innerHTML=`<div class="metric-grid">${metric('Open',items.filter(x=>x.status==='open').length,'Unplanned work')}${metric('In progress',items.filter(x=>x.status==='in_progress').length,'Active maintenance','warning')}${metric('Blocked',items.filter(x=>x.status==='blocked').length,'Needs intervention','critical')}${metric('Verified',items.filter(x=>x.status==='verified').length,'Operationally accepted','good')}</div>${panel('Maintenance backlog',`<div class="table-wrap"><table><thead><tr><th>ID</th><th>Work order</th><th>Priority</th><th>Status</th><th>Team</th><th>Due</th><th>Action</th></tr></thead><tbody>${items.map(x=>`<tr><td>#${x.id}</td><td><strong>${escapeHtml(x.title)}</strong><br><small>${escapeHtml(x.description)}</small></td><td>${badge(x.priority)}</td><td>${badge(x.status)}</td><td>${escapeHtml(x.assigned_team||'Unassigned')}</td><td>${timeFmt(x.due_at)}</td><td><button class="secondary work-order-open" data-id="${x.id}" data-status="${x.status}">Advance</button></td></tr>`).join('')}</tbody></table></div>`)}<div id="work-order-result" style="margin-top:14px"></div>`;
  document.querySelectorAll('.work-order-open').forEach(button=>button.onclick=()=>advanceWorkOrder(Number(button.dataset.id),button.dataset.status));
}

async function advanceWorkOrder(id,current){
  const next={open:'planned',planned:'in_progress',in_progress:'completed',blocked:'in_progress',completed:'verified'}[current];
  if(!next){toast('No automatic next transition is available');return;}
  const payload={status:next};
  if(next==='completed')payload.completion_notes=prompt('Completion notes are required')||'';
  await api(`/work-orders/${id}/transition`,{method:'POST',body:JSON.stringify(payload)});
  toast(`Work order moved to ${next.replaceAll('_',' ')}`);renderWorkOrders();
}

async function renderReports(){
  setTitle('OPERATIONAL EVIDENCE','Reports and exports');
  const reports=['daily-terminal-operations','vessel-calls','berth-utilization','yard-occupancy','container-dwell-exceptions','gate-performance','safety-incidents','equipment-health','maintenance-work-orders','reefer-exceptions'];
  $('#content').innerHTML=`${panel('Report catalog',`<div class="report-grid">${reports.map(name=>`<article class="action-row report-card"><div><strong>${name.replaceAll('-',' ')}</strong><p>Generated from organization-scoped persisted records</p></div><div class="toolbar"><button class="secondary report-export" data-name="${name}" data-format="pdf">PDF</button><button class="secondary report-export" data-name="${name}" data-format="csv">CSV</button><button class="secondary report-preview" data-name="${name}">Preview</button></div></article>`).join('')}</div>`)}<div id="report-preview" style="margin-top:14px"></div>`;
  document.querySelectorAll('.report-export').forEach(button=>button.onclick=()=>downloadAuthorized(`/reports/${button.dataset.name}/${button.dataset.format}`,`${button.dataset.name}.${button.dataset.format}`));
  document.querySelectorAll('.report-preview').forEach(button=>button.onclick=async()=>{const data=await api(`/reports/${button.dataset.name}/json`);$('#report-preview').innerHTML=panel(`${button.dataset.name.replaceAll('-',' ')} preview`,`<div class="notice">Generated ${timeFmt(data.generated_at)} · ${escapeHtml(data.terminal)} · ${data.demo_data?'Synthetic demo data':''}</div><pre>${escapeHtml(JSON.stringify(data,null,2))}</pre>`)});
}

async function renderHealth(){
  setTitle('PLATFORM RELIABILITY','System health');
  const health=await api('/health/ready');
  const components=health.components||{};
  $('#content').innerHTML=`<div class="metric-grid">${metric('API',health.status,'Readiness aggregate',health.status==='ready'?'good':'warning')}${metric('Database',health.database,components.database?.adapter||'Persistence','good')}${metric('Redis',health.redis,components.redis?.required?'Required':'Optional',health.redis==='ok'?'good':'')}${metric('Worker',health.worker||'unknown',components.worker?.age_seconds!=null?`${components.worker.age_seconds}s heartbeat age`:'Heartbeat adapter',health.worker==='ok'?'good':'warning')}${metric('Storage',health.storage,'Evidence and report adapter','good')}</div><div class="grid-2">${panel('Dependency detail',`<pre>${escapeHtml(JSON.stringify(components,null,2))}</pre>`)}${panel('Recovery behavior',`<div class="action-card"><div class="action-row"><div><strong>Database</strong><p>Pool pre-ping and readiness query</p></div>${badge(health.database)}</div><div class="action-row"><div><strong>Event stream</strong><p>Automatic browser reconnection</p></div>${badge('online')}</div><div class="action-row"><div><strong>Worker</strong><p>Timestamped heartbeat with stale detection</p></div>${badge(health.worker||'unknown')}</div><div class="action-row"><div><strong>Storage</strong><p>Read/write probe without exposing host paths</p></div>${badge('ok')}</div></div><a href="/api/v1/docs" target="_blank" class="secondary api-docs-link">Open API documentation</a>`)}</div>`;
}

async function renderAudit(){ setTitle('GOVERNANCE','Append-only audit log'); let audit=[]; try{audit=await api('/audit?limit=120')}catch{/* role may not access */} $('#content').innerHTML=`${panel('Audit trail',audit.length?`<div class="table-wrap"><table><thead><tr><th>Time</th><th>Action</th><th>Entity</th><th>User</th><th>Details</th></tr></thead><tbody>${audit.map(x=>`<tr><td>${timeFmt(x.created_at)}</td><td>${escapeHtml(x.action)}</td><td>${x.entity_type}:${x.entity_id||'—'}</td><td>${x.user_id||'system'}</td><td style="white-space:normal;max-width:420px">${escapeHtml(JSON.stringify(x.details))}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Audit records require director or administrator permission.</div>')}<div class="notice" style="margin-top:14px">Normal application routes only append audit records; they do not expose update or delete operations for this history.</div>`; }

async function runScenario(name){ toast(`Running ${name.replaceAll('_',' ')}…`); const result=await api('/simulation/run',{method:'POST',body:JSON.stringify({scenario:name,speed_multiplier:10})}); toast(`${name.replaceAll('_',' ')} completed: ${result.events_created} event(s)`); const target=$('#scenario-result'); if(target)target.innerHTML=panel('Scenario result',`<pre>${escapeHtml(JSON.stringify(result,null,2))}</pre>`); }
function wireCommonActions(){ document.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>runScenario(b.dataset.scenario)); document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go)); const r=$('#daily-report'); if(r)r.onclick=()=>downloadAuthorized('/reports/daily.pdf','daily-terminal-operations.pdf'); }
async function downloadAuthorized(path,name){ const response=await fetch(`${API}${path}`,{headers:{Authorization:`Bearer ${state.token}`}}); if(!response.ok)throw new Error('Export failed'); downloadBlob(await response.blob(),name); }
function downloadBlob(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

const views={command:renderCommand,twin:renderTwin,vessels:renderVessels,yard:renderYard,containers:renderContainers,gate:renderGate,safety:renderSafety,incidents:renderIncidents,equipment:renderEquipment,workorders:renderWorkOrders,reefers:renderReefers,analytics:renderAnalytics,dataset:renderDataset,reports:renderReports,simulation:renderSimulation,audit:renderAudit,health:renderHealth};
async function navigate(view){ state.view=view; document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view)); $('#content').innerHTML='<div class="empty">Loading operational data…</div>'; try{await views[view]();}catch(e){$('#content').innerHTML=panel('Unable to load',`<div class="notice" style="border-color:var(--red)">${escapeHtml(e.message)}</div>`);}}

$('#login-form').addEventListener('submit',async e=>{e.preventDefault();$('#login-error').textContent='';try{await login($('#email').value,$('#password').value)}catch(err){$('#login-error').textContent=err.message}});
$('#logout').onclick=logout;
document.querySelectorAll('#nav button').forEach(b=>b.onclick=()=>navigate(b.dataset.view));
setInterval(()=>{$('#clock').textContent=new Date().toLocaleString()},1000);
restore();
